fn element_wise_modulo(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Since both a and b have the same length, we can safely zip them.
    // For each pair, calculate a[i] % b[i].
    // Assumes b[i] != 0 as stated in the problem.
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x % y)
        .collect()
}